import java.util.*;
import java.io.*;

public class Main {
    static final int MAX = 270005;
    static int n, m, k, mod;
    static int[][] f = new int[19][MAX];
    static List<Long> g = new ArrayList<>();
    static int[] count_bits = new int[MAX];

    static int mod_adjust(int x) {
        if (x < 0) return x + mod;
        if (x >= mod) return x - mod;
        return x;
    }

    static void update(IntWrapper x, int y) {
        x.value = mod_adjust(x.value + y);
    }

    static int bin_pow(int base, int exp) {
        int res = 1;
        while (exp != 0) {
            if ((exp & 1) != 0) res = (int)((long)res * base % mod);
            base = (int)((long)base * base % mod);
            exp >>= 1;
        }
        return res;
    }

    static int[] fact = new int[MAX];
    static int[] inv_fact = new int[MAX];

    static void precompute(int n) {
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = (int)((long)fact[i - 1] * i % mod);
        }
        inv_fact[n] = bin_pow(fact[n], mod - 2);
        for (int i = n - 1; i >= 0; i--) {
            inv_fact[i] = (int)((long)inv_fact[i + 1] * (i + 1) % mod);
        }
    }

    static void transform_array(int[] arr, int size, int h) {
        for (int p = 1; p < size; p <<= 1) {
            for (int i = 0; i < size; i += p << 1) {
                for (int k = i; k < i + p; k++) {
                    update(new IntWrapper(arr[k + p]), h * arr[k]);
                    arr[k + p] = ((IntWrapper) new IntWrapper(arr[k + p])).value;
                }
            }
        }
    }

    static class IntWrapper {
        int value;
        IntWrapper(int v) { value = v; }
    }

    static class Vector {
        List<Long> data;

        Vector() {
            data = new ArrayList<>();
        }

        Vector(List<Long> list) {
            data = new ArrayList<>(list);
        }

        static Vector multiply(Vector A, Vector B, int l, int mod) {
            List<Long> C = new ArrayList<>(Collections.nCopies(l + 1, 0L));
            for (int i = 0; i <= l; i++) {
                for (int j = 0; j <= l - i; j++) {
                    long val = C.get(i + j) + A.data.get(i) * B.data.get(j);
                    C.set(i + j, val % mod);
                }
            }
            return new Vector(C);
        }

        static Vector powSeries(Vector A, int k, int l, int mod) {
            Vector C = new Vector();
            C.data = new ArrayList<>(Collections.nCopies(l + 1, 0L));
            C.data.set(0, 1L);
            Vector base = new Vector(A.data);
            while (k > 0) {
                if ((k & 1) != 0) {
                    C = multiply(C, base, l, mod);
                }
                base = multiply(base, base, l, mod);
                k >>= 1;
            }
            return C;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        mod = Integer.parseInt(st.nextToken());

        precompute(n);
        if ((n & 1) == 1) {
            System.out.println(bin_pow(k, n));
            return;
        }

        m = 1;
        while (m <= n) m <<= 1;
        int l = 0;
        for (int i = 0; i < 31; i++) {
            if ((m & (1 << i)) != 0) {
                l = i;
            }
        }

        for (int i = 0; i < m; i++) {
            count_bits[i] = Integer.bitCount(i);
        }
        precompute(m);
        for (int i = 0; i < m; i++) {
            f[count_bits[i]][i] = inv_fact[i];
        }

        for (int i = 0; i <= l; i++) {
            int[] arr = new int[m];
            for (int j = 0; j < m; j++) {
                arr[j] = f[i][j];
            }
            transform_array(arr, m, 1);
            for (int j = 0; j < m; j++) {
                f[i][j] = arr[j];
            }
        }

        g = new ArrayList<>(Collections.nCopies(l + 1, 0L));
        for (int s = 0; s < m; s++) {
            for (int i = 0; i <= l; i++) {
                g.set(i, (long)f[i][s]);
            }
            Vector G = new Vector(g);
            G = Vector.powSeries(G, k, l, mod);
            for (int i = 0; i <= l; i++) {
                f[i][s] = G.data.get(i).intValue();
            }
        }

        int[] arrN = new int[m];
        for (int i = 0; i < m; i++) {
            arrN[i] = f[count_bits[n]][i];
        }
        transform_array(arrN, m, -1);
        int result = mod_adjust(bin_pow(k, n) - (int)((long)arrN[n] * fact[n] % mod));
        System.out.println(result);
    }
}

